PTX_SOURCE = r'''
.version 7.0
.target sm_80
.address_size 64

// -----------------------------------------------------------------------------
// Kernel: softmax_kernel
// Implements row‑wise softmax for a (batch, dim) fp16 tensor.
// Arguments:
//   .param .u64 out_ptr   // output pointer (fp16)
//   .param .u64 in_ptr    // input pointer  (fp16)
//   .param .u32 batch     // batch size
//   .param .u32 dim       // number of features per row
// -----------------------------------------------------------------------------
// Launch configuration:
//   grid  = (batch, 1, 1)
//   block = (256, 1, 1)
.visible .entry softmax_kernel(
    .param .u64 out_ptr,
    .param .u64 in_ptr,
    .param .u32 batch,
    .param .u32 dim
)
{
    // -------------------------------------------------
    // Load kernel parameters
    // -------------------------------------------------
    .reg .u64   %out_ptr, %in_ptr;
    .reg .u32   %batch, %dim;
    .reg .u32   %row_idx, %tid, %ntid;
    .reg .u64   %row_offset, %in_row, %out_row;
    .reg .pred  %p;

    ld.param.u64    %out_ptr, [out_ptr];
    ld.param.u64    %in_ptr,  [in_ptr];
    ld.param.u32    %batch,   [batch];
    ld.param.u32    %dim,     [dim];

    // thread identifiers
    mov.u32 %tid,  %tid.x;
    mov.u32 %ntid, %ntid.x;

    // each block processes one row
    mov.u32 %row_idx, %ctaid.x;
    setp.ge.u32 %p, %row_idx, %batch;
    @%p bra DONE;                     // out of bounds

    // -----------------------------------------------------------------
    // Compute byte offset of the row (fp16 = 2 bytes)
    // -----------------------------------------------------------------
    mul.lo.u32   %row_offset, %row_idx, %dim;   // elements
    mul.wide.u32 %row_offset, %row_offset, 2;   // bytes

    add.u64 %in_row,  %in_ptr,  %row_offset;
    add.u64 %out_row, %out_ptr, %row_offset;

    // -----------------------------------------------------------------
    // 1) Compute row‑wise maximum (fp32 accumulation)
    // -----------------------------------------------------------------
    .reg .f32   %max_val, %elem_f32, %temp_max;
    .reg .f16   %elem_f16;
    .reg .u32   %i;

    // initialise with -inf
    mov.f32 %max_val, -3.402823466e38;

    mov.u32 %i, %tid;
MAX_LOOP:
    setp.ge.u32 %p, %i, %dim;
    @%p bra MAX_DONE;

    // address = in_row + i*2
    mad.wide.u32 %row_offset, %i, 2, %in_row;
    ld.global.f16 %elem_f16, [%row_offset];
    cvt.f32.f16 %elem_f32, %elem_f16;
    max.f32 %max_val, %max_val, %elem_f32;

    add.u32 %i, %i, %ntid;
    bra MAX_LOOP;
MAX_DONE:

    // store per‑thread max into shared memory
    .shared .align 4 .b32 sdata[256];
    st.shared.f32 [sdata + %tid * 4], %max_val;
    bar.sync 0;

    // parallel reduction (binary tree) for max
    .reg .u32 %offset;
    mov.u32 %offset, %ntid;
REDUCE_MAX:
    shr.u32 %offset, %offset, 1;
    setp.lt.u32 %p, %tid, %offset;
    @%p bra REDUCE_MAX_SKIP;
    ld.shared.f32 %temp_max, [sdata + %tid * 4];
    ld.shared.f32 %elem_f32, [sdata + %offset * 4];
    max.f32 %temp_max, %temp_max, %elem_f32;
    st.shared.f32 [sdata + %tid * 4], %temp_max;
REDUCE_MAX_SKIP:
    bar.sync 0;
    setp.eq.u32 %p, %offset, 1;
    @%p bra REDUCE_MAX_DONE;
    bra REDUCE_MAX;
REDUCE_MAX_DONE:
    // final max is in sdata[0]
    ld.shared.f32 %max_val, [sdata];

    // -----------------------------------------------------------------
    // 2) Compute exponentials and sum (fp32 accumulation)
    // -----------------------------------------------------------------
    .reg .f32   %sum_val, %exp_val;
    mov.f32 %sum_val, 0.0;

    mov.u32 %i, %tid;
EXP_LOOP:
    setp.ge.u32 %p, %i, %dim;
    @%p bra EXP_DONE;

    mad.wide.u32 %row_offset, %i, 2, %in_row;
    ld.global.f16 %elem_f16, [%row_offset];
    cvt.f32.f16 %elem_f32, %elem_f16;
    sub.f32 %elem_f32, %elem_f32, %max_val;          // x - max
    exp.approx.f32 %exp_val, %elem_f32;             // e^{x-max}
    add.f32 %sum_val, %sum_val, %exp_val;

    add.u32 %i, %i, %ntid;
    bra EXP_LOOP;
EXP_DONE:

    // store per‑thread sum into shared memory
    st.shared.f32 [sdata + %tid * 4], %sum_val;
    bar.sync 0;

    // reduction for sum (addition)
    mov.u32 %offset, %ntid;
REDUCE_SUM:
    shr.u32 %offset, %offset, 1;
    setp.lt.u32 %p, %tid, %offset;
    @%p bra REDUCE_SUM_SKIP;
    ld.shared.f32 %temp_max, [sdata + %tid * 4];
    ld.shared.f32 %elem_f32, [sdata + %offset * 4];
    add.f32 %temp_max, %temp_max, %elem_f32;
    st.shared.f32 [sdata + %tid * 4], %temp_max;
REDUCE_SUM_SKIP:
    bar.sync 0;
    setp.eq.u32 %p, %offset, 1;
    @%p bra REDUCE_SUM_DONE;
    bra REDUCE_SUM;
REDUCE_SUM_DONE:
    ld.shared.f32 %sum_val, [sdata];   // row‑wise sum of exp

    // -----------------------------------------------------------------
    // 3) Write final softmax values
    // -----------------------------------------------------------------
    mov.u32 %i, %tid;
WRITE_LOOP:
    setp.ge.u32 %p, %i, %dim;
    @%p bra WRITE_DONE;

    // reload original element
    mad.wide.u32 %row_offset, %i, 2, %in_row;
    ld.global.f16 %elem_f16, [%row_offset];
    cvt.f32.f16 %elem_f32, %elem_f16;
    sub.f32 %elem_f32, %elem_f32, %max_val;          // x - max
    exp.approx.f32 %exp_val, %elem_f32;             // e^{x-max}
    div.f32 %elem_f32, %exp_val, %sum_val;          // softmax

    // convert back to fp16 (round‑to‑nearest)
    cvt.rn.f16.f32 %elem_f16, %elem_f32;

    // store
    mad.wide.u32 %row_offset, %i, 2, %out_row;
    st.global.f16 [%row_offset], %elem_f16;

    add.u32 %i, %i, %ntid;
    bra WRITE_LOOP;
WRITE_DONE:

DONE:
    ret;
}
